#!/usr/bin/env node
// Vendored copy of a shared language checker. Kept in sync by hand: changes go upstream first,
// then are copied here. Do not edit this file directly.
// Fails when tracked files contain Cyrillic in comments (code files) or anywhere (Markdown).
// Usage: node check-language.mjs [repo-root]   (default: current directory)
// Config: .language-check.json in the repo root: { "allow": [{path, category, reason}], "strict": [glob] }
// Exit codes: 0 clean, 1 findings, 2 config or environment error.

import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { basename, extname, join, resolve } from "node:path";

const CYRILLIC = /[Ѐ-ԯ]/;
const WORD_CHAR = /[\p{L}\p{N}_]/u;
const UTF8 = new TextDecoder("utf-8", { fatal: true });

// String delimiter kinds: `multiline` lets the string span lines; `escape` is the escape
// character inside it ("" for none); `doubled` makes a doubled quote an escaped quote.
const SL = { multiline: false, escape: "\\" };
const ML = { multiline: true, escape: "\\" };
const SL_RAW = { multiline: false, escape: "" };
const ML_RAW = { multiline: true, escape: "" };
// A doubled quote ('it''s') is an escaped quote: YAML and SQL single quotes.
const ML_DOUBLED = { multiline: true, escape: "", doubled: true };

// Comment and string syntax of each language family. The scanner is a small tokenizer, not a
// parser: a construct it does not understand may cost at most its own line, never the rest of
// the file, so an unclosed string or comment ends at the end of its line.
//   line:     line-comment openers.
//   block:    [open, close] block-comment pairs.
//   nested:   block comments nest (Rust).
//   hash:     "#" opens a line comment: "anywhere" outside strings, or "word" only at the start
//             of a word (line start or after whitespace), as in shell and YAML.
//   quotes:   { quote character: SL | ML | ... } string delimiters.
//   template: backtick template literals with nested `${...}` expressions (JS/TS).
//   regex:    `/.../` regex literals (JS/TS), told apart from division by the preceding token.
//   urls:     "//" right after "scheme:" is part of a URL, not a comment (JS/TS text in JSX).
//   cssUrl:   an unquoted url(...) is data, so url(//cdn...) is not a comment (SCSS).
//   rust:     Rust raw strings (r#"..."#) and char literals vs lifetimes.
//   python:   Python triple-quoted strings; docstrings count as comments.
//   triple:   TOML multi-line strings ("""...""" and '''...''').
//   heredoc:  shell syntax: here-documents (<<EOF ... EOF) are data, and $'...' strings take
//             backslash escapes.
//   scalarStart: a quote opens a string only at the start of a YAML scalar (after ":", "-",
//             "[", "{", "," or at line start); elsewhere it is plain text.
//   wordQuote: an apostrophe inside a word (don't, or a Ukrainian word) does not open a string.
const FAMILIES = {
  rust: { line: ["//"], block: [["/*", "*/"]], nested: true, quotes: { '"': ML }, rust: true },
  cstyle: {
    line: ["//"],
    block: [["/*", "*/"]],
    quotes: { '"': SL, "'": SL },
    template: true,
    regex: true,
    urls: true,
  },
  css: { block: [["/*", "*/"]], quotes: { '"': SL, "'": SL } },
  scss: { line: ["//"], block: [["/*", "*/"]], quotes: { '"': SL, "'": SL }, urls: true, cssUrl: true },
  powershell: {
    hash: "word",
    block: [["<#", "#>"]],
    quotes: { '"': { multiline: false, escape: "`" }, "'": { multiline: false, escape: "", doubled: true } },
  },
  sql: { line: ["--"], block: [["/*", "*/"]], quotes: { '"': ML_DOUBLED, "'": ML_DOUBLED } },
  python: { hash: "anywhere", quotes: { '"': SL, "'": SL }, python: true },
  shell: { hash: "word", quotes: { '"': ML, "'": ML_RAW }, heredoc: true, wordQuote: true },
  yaml: { hash: "word", quotes: { '"': ML, "'": ML_DOUBLED }, scalarStart: true },
  toml: { hash: "anywhere", quotes: { '"': SL, "'": SL_RAW }, triple: true },
  hash: { hash: "word", quotes: { '"': SL, "'": SL }, wordQuote: true },
  html: { block: [["<!--", "-->"]] },
};

const EXT = {
  ".rs": "rust",
  ".ts": "cstyle", ".tsx": "cstyle", ".js": "cstyle", ".jsx": "cstyle",
  ".mjs": "cstyle", ".cjs": "cstyle", ".mts": "cstyle", ".cts": "cstyle",
  ".py": "python", ".pyi": "python",
  ".sh": "shell", ".bash": "shell", ".zsh": "shell",
  ".ps1": "powershell",
  ".yml": "yaml", ".yaml": "yaml", ".toml": "toml",
  ".css": "css", ".scss": "scss",
  ".sql": "sql",
  ".html": "html", ".htm": "html",
  ".dockerfile": "hash",
};
const NAMES = {
  Dockerfile: "hash", Containerfile: "hash",
  Makefile: "hash", makefile: "hash", GNUmakefile: "hash",
};

// The syntax family of a file, or undefined when it is not scanned. `head` lazily returns the
// file's first bytes, read only for extensionless files that may carry a shebang.
function familyOf(path, head) {
  const name = basename(path);
  const ext = extname(path).toLowerCase();
  if (NAMES[name]) return NAMES[name];
  if (/^(Dockerfile|Containerfile)\./.test(name)) return "hash";
  if (EXT[ext]) return EXT[ext];
  if (ext !== "" && !name.startsWith(".")) return undefined;
  const first = /^#!.*/.exec(head())?.[0] ?? "";
  if (/\b(sh|bash|zsh|dash|ksh)\b/.test(first)) return "shell";
  if (/\bpython[0-9.]*\b/.test(first)) return "python";
  return undefined;
}
const MARKDOWN = new Set([".md", ".mdx"]);

// After one of these characters a "/" starts a regex literal; after anything else it divides.
const REGEX_AFTER = new Set("(,=:[!&|?{};+-*%~^");
const REGEX_AFTER_WORD = new Set([
  "return", "typeof", "instanceof", "in", "of", "new", "delete", "void", "throw", "case", "do",
  "else", "yield", "await",
]);

function globToRegExp(glob) {
  let re = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*" && glob[i + 1] === "*") {
      i++;
      if (glob[i + 1] === "/") {
        i++;
        re += "(?:.*/)?";
      } else re += ".*";
    } else if (c === "*") re += "[^/]*";
    else if (c === "?") re += "[^/]";
    else re += c.replace(/[.+^${}()|[\]\\]/g, "\\$&");
  }
  return new RegExp(`^${re}$`);
}

// A config path: a glob, or a plain path that matches the file itself or a directory's contents
// ("src/locales", "src/locales/"). A leading "./" is ignored.
function pathMatcher(pattern) {
  const p = pattern.replace(/^(\.\/)+/, "");
  if (/[*?]/.test(p)) return globToRegExp(p);
  const plain = p.replace(/\/+$/, "").replace(/[.+^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`^${plain}(?:/.*)?$`);
}

// Config and environment errors exit 2 with one line, so they never look like findings (1).
function fail(message) {
  console.error(`language-check: ${message.split("\n")[0]}`);
  process.exit(2);
}

function loadConfig(root) {
  const file = join(root, ".language-check.json");
  if (!existsSync(file)) return { allow: [], strict: [] };
  let cfg;
  try {
    cfg = JSON.parse(readFileSync(file, "utf8"));
  } catch (e) {
    fail(`.language-check.json: invalid JSON: ${e.message}`);
  }
  if (cfg === null || typeof cfg !== "object" || Array.isArray(cfg)) {
    fail(".language-check.json: must be a JSON object");
  }
  const allow = cfg.allow ?? [];
  const strict = cfg.strict ?? [];
  if (!Array.isArray(allow) || !Array.isArray(strict)) {
    fail(".language-check.json: allow and strict must be arrays");
  }
  allow.forEach((a, i) => {
    for (const k of ["path", "category", "reason"]) {
      if (typeof a?.[k] !== "string" || a[k].trim() === "") {
        fail(`.language-check.json: allow[${i}] needs a non-empty "${k}"`);
      }
    }
  });
  strict.forEach((s, i) => {
    if (typeof s !== "string") fail(`.language-check.json: strict[${i}] must be a glob string`);
  });
  return {
    allow: allow.map((a) => ({ path: a.path, re: pathMatcher(a.path), used: false })),
    strict: strict.map(pathMatcher),
  };
}

function lineEnd(text, pos) {
  const j = text.indexOf("\n", pos);
  return j === -1 ? text.length : j;
}

// Skips a string that opens at `start` with `quote`; returns the index after it. An unclosed
// string, or a single-line string cut by a newline, ends at the end of its line.
function skipString(text, start, quote, kind) {
  let j = start + 1;
  while (j < text.length) {
    const ch = text[j];
    if (kind.escape && ch === kind.escape) {
      j += 2;
      continue;
    }
    if (ch === quote && kind.doubled && text[j + 1] === quote) {
      j += 2;
      continue;
    }
    if (ch === quote) return j + 1;
    if (ch === "\n" && !kind.multiline) return j;
    j++;
  }
  return lineEnd(text, start);
}

// Skips a """ or ''' string opening at `start`; an unclosed one ends at the end of its line.
function skipTriple(text, start, escape) {
  const q = text.slice(start, start + 3);
  let j = start + 3;
  while (j < text.length) {
    if (escape && text[j] === escape) j += 2;
    else if (text.startsWith(q, j)) return j + 3;
    else j++;
  }
  return lineEnd(text, start);
}

// For a shell line break at `pos` with pending here-documents, returns the index of the line
// break that ends the last terminator line, or `pos` when a terminator is missing.
function skipHeredocs(text, pos, delims) {
  let at = pos;
  for (const { delim } of delims) {
    let from = at + 1;
    let found = -1;
    while (from <= text.length) {
      const to = lineEnd(text, from);
      if (text.slice(from, to).trim() === delim) {
        found = to;
        break;
      }
      if (to >= text.length) break;
      from = to + 1;
    }
    if (found === -1) return pos;
    at = found;
  }
  return at;
}

// Skips a JS template literal opening at `start`, including nested `${...}` expressions.
function skipTemplate(text, start) {
  let j = start + 1;
  while (j < text.length) {
    const ch = text[j];
    if (ch === "\\") j += 2;
    else if (ch === "`") return j + 1;
    else if (ch === "$" && text[j + 1] === "{") {
      j = skipTemplateExpr(text, j + 2);
      if (j === -1) break;
    } else j++;
  }
  return lineEnd(text, start);
}

// Skips the inside of `${...}`; returns the index after the closing brace, or -1 if unclosed.
function skipTemplateExpr(text, start) {
  let depth = 1;
  let j = start;
  while (j < text.length) {
    const ch = text[j];
    if (ch === "{") depth++;
    else if (ch === "}" && --depth === 0) return j + 1;
    if (ch === "`") {
      j = skipTemplate(text, j);
      continue;
    }
    if (ch === "'" || ch === '"') {
      j = skipString(text, j, ch, SL);
      continue;
    }
    j++;
  }
  return -1;
}

// Returns the index after a regex literal opening at `start`, or -1 when the line has no
// closing slash (then it was not a regex).
function skipRegex(text, start) {
  let j = start + 1;
  let inClass = false;
  while (j < text.length && text[j] !== "\n") {
    const ch = text[j];
    if (ch === "\\") j += 2;
    else {
      if (ch === "[") inClass = true;
      else if (ch === "]") inClass = false;
      else if (ch === "/" && !inClass) {
        j++;
        while (j < text.length && /[a-z]/i.test(text[j])) j++;
        return j;
      }
      j++;
    }
  }
  return -1;
}

// Whether a "/" at `pos`, with `prev` the index of the last code character, opens a regex.
function opensRegex(text, prev) {
  if (prev < 0) return true;
  const p = text[prev];
  if (REGEX_AFTER.has(p)) return true;
  if (p === ">" && text[prev - 1] === "=") return true;
  if (/[\w$]/.test(p)) {
    const word = /[\w$]+$/.exec(text.slice(Math.max(0, prev - 15), prev + 1))[0];
    return REGEX_AFTER_WORD.has(word);
  }
  return false;
}

// Whether a Python triple-quoted string from `start` to `stop` is a docstring (or a bare string
// used as a comment): it is a statement of its own. Only a string prefix (r, u, f, b) may precede
// it on its line, only a comment may follow it, and the previous code line either ends a block
// header (":") or is a complete statement. A string inside brackets or after "=" is data.
function isDocstring(text, lineFrom, start, stop) {
  if (!/^\s*[rRuUbBfF]{0,2}$/.test(text.slice(lineFrom, start))) return false;
  if (!/^[ \t]*(#.*)?$/m.test(text.slice(stop, lineEnd(text, stop)))) return false;
  // Walk back line by line to the previous code line.
  let to = lineFrom - 1;
  while (to > 0) {
    const from = text.lastIndexOf("\n", to - 1) + 1;
    const line = text.slice(from, to).replace(/\s#.*$/, "").trimEnd();
    if (line !== "" && !line.trimStart().startsWith("#")) return !/[([{,\\=+\-*/%&|^<>]$/.test(line);
    to = from - 1;
  }
  return true;
}

// Returns [{start, end}] character ranges of comments in `text`.
function commentRanges(text, fam) {
  const ranges = [];
  const n = text.length;
  let i = 0;
  let prev = -1; // index of the last code (non-comment, non-space) character
  const startsWith = (s) => text.startsWith(s, i);
  const lineStart = (pos) => text.lastIndexOf("\n", pos - 1) + 1;
  const code = (to) => {
    prev = to - 1;
    i = to;
  };

  const heredocs = [];

  while (i < n) {
    const c = text[i];

    if (c === "\n" && heredocs.length) {
      i = skipHeredocs(text, i, heredocs.splice(0)) + 1;
      continue;
    }
    if (fam.heredoc && startsWith("<<") && !startsWith("<<<")) {
      const m = /^<<-?[ \t]*(["']?)([A-Za-z_][\w.-]*)\1/.exec(text.slice(i, i + 80));
      if (m) {
        heredocs.push({ delim: m[2] });
        code(i + m[0].length);
        continue;
      }
    }

    if (fam.triple && (startsWith('"""') || startsWith("'''"))) {
      code(skipTriple(text, i, c === '"' ? "\\" : ""));
      continue;
    }

    if (fam.python && (startsWith('"""') || startsWith("'''"))) {
      const q = text.slice(i, i + 3);
      const end = text.indexOf(q, i + 3);
      if (end === -1) {
        code(lineEnd(text, i));
        continue;
      }
      const stop = end + 3;
      if (isDocstring(text, lineStart(i), i, stop)) ranges.push({ start: i, end: stop });
      code(stop);
      continue;
    }

    const block = fam.block?.find(([open]) => startsWith(open));
    if (block) {
      const [open, close] = block;
      let depth = 1;
      let j = i + open.length;
      while (j < n && depth > 0) {
        if (fam.nested && text.startsWith(open, j)) {
          depth++;
          j += open.length;
        } else if (text.startsWith(close, j)) {
          depth--;
          j += close.length;
        } else j++;
      }
      if (depth > 0) j = lineEnd(text, i);
      ranges.push({ start: i, end: j });
      i = j;
      continue;
    }

    const isUrl = fam.urls && startsWith("//") && text[i - 1] === ":" && /[a-z]/i.test(text[i - 2] ?? "");
    const isLine =
      (!isUrl && fam.line?.some((o) => startsWith(o))) ||
      (fam.hash && c === "#" && (fam.hash === "anywhere" || i === 0 || /\s/.test(text[i - 1])));
    if (isLine) {
      const j = lineEnd(text, i);
      ranges.push({ start: i, end: j });
      i = j;
      continue;
    }

    if (fam.rust) {
      // Raw strings: r"..", r#".."#, br#".."#.
      if ((c === "r" || (c === "b" && text[i + 1] === "r")) && !/\w/.test(text[i - 1] ?? "")) {
        const m = /^b?r(#*)"/.exec(text.slice(i, i + 300));
        if (m) {
          const close = `"${m[1]}`;
          const end = text.indexOf(close, i + m[0].length);
          code(end === -1 ? lineEnd(text, i) : end + close.length);
          continue;
        }
      }
      // A quote is a char literal only when it closes within the literal; otherwise a lifetime.
      if (c === "'") {
        const m = /^'(?:\\(?:u\{[0-9a-fA-F_]+\}|x[0-9a-fA-F]{2}|.)|[^\\'\n])'/u.exec(text.slice(i, i + 14));
        code(i + (m ? m[0].length : 1));
        continue;
      }
    }

    if (fam.cssUrl && /^url\(\s*[^'"\s]/i.test(text.slice(i, i + 6))) {
      const close = text.indexOf(")", i);
      code(close === -1 || close > lineEnd(text, i) ? lineEnd(text, i) : close + 1);
      continue;
    }

    if (fam.template && c === "`") {
      code(skipTemplate(text, i));
      continue;
    }

    if (fam.regex && c === "/" && opensRegex(text, prev)) {
      const end = skipRegex(text, i);
      if (end !== -1) {
        code(end);
        continue;
      }
    }

    let kind = fam.quotes?.[c];
    // Shell ANSI-C quoting: inside $'...' a backslash escapes the quote.
    if (fam.heredoc && c === "'" && text[i - 1] === "$") kind = ML;
    if (kind) {
      // An apostrophe inside a word does not open a string.
      if (c === "'" && fam.wordQuote && WORD_CHAR.test(text[i - 1] ?? "")) {
        code(i + 1);
        continue;
      }
      if (fam.scalarStart && !/(^|[:\-[{,?])\s*$/.test(text.slice(lineStart(i), i))) {
        code(i + 1);
        continue;
      }
      code(skipString(text, i, c, kind));
      continue;
    }

    if (/\s/.test(c)) i++;
    else code(i + 1);
  }
  return ranges;
}

function lineOf(offsets, pos) {
  let lo = 0;
  let hi = offsets.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (offsets[mid] <= pos) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

function findings(text, ranges) {
  const lines = text.split("\n");
  const offsets = [];
  let off = 0;
  for (const l of lines) {
    offsets.push(off);
    off += l.length + 1;
  }
  const hit = new Set();
  for (const { start, end } of ranges) {
    const piece = text.slice(start, end);
    if (!CYRILLIC.test(piece)) continue;
    let pos = start;
    for (const seg of piece.split("\n")) {
      if (CYRILLIC.test(seg)) hit.add(lineOf(offsets, pos));
      pos += seg.length + 1;
    }
  }
  return [...hit]
    .sort((a, b) => a - b)
    .map((n) => ({ line: n + 1, text: lines[n].trim() }));
}

function main() {
  const root = resolve(process.argv[2] ?? ".");
  const { allow, strict } = loadConfig(root);
  let listed;
  try {
    listed = execFileSync("git", ["ls-files", "-z", "--cached", "--others", "--exclude-standard"], {
      cwd: root,
      encoding: "utf8",
      maxBuffer: 256 * 1024 * 1024,
      stdio: ["ignore", "pipe", "pipe"],
    });
  } catch (e) {
    fail(`git ls-files failed in ${root}: ${(e.stderr || e.message).trim()}`);
  }
  const files = [...new Set(listed.split("\0").filter(Boolean))].sort();
  let failed = false;

  for (const path of files) {
    const allowed = allow.filter((a) => a.re.test(path));
    allowed.forEach((a) => (a.used = true));
    if (allowed.length) continue;
    let buf;
    const read = () => {
      try {
        buf ??= readFileSync(join(root, path));
      } catch {
        buf = null;
      }
      return buf;
    };
    const family = familyOf(path, () => read()?.subarray(0, 200).toString("latin1") ?? "");
    const whole = strict.some((re) => re.test(path)) || MARKDOWN.has(extname(path).toLowerCase());
    if (!whole && !family) continue;
    if (!read()) continue;
    const utf16 = buf.length >= 2 && ((buf[0] === 0xff && buf[1] === 0xfe) || (buf[0] === 0xfe && buf[1] === 0xff));
    if (!utf16 && buf.includes(0)) continue;
    let text;
    try {
      if (utf16) throw new Error("UTF-16");
      text = UTF8.decode(buf);
    } catch {
      // A legacy encoding (windows-1251, UTF-16) would hide Cyrillic from the check.
      const loose = buf.toString("utf8");
      const line = utf16 ? 1 : loose.slice(0, loose.indexOf("�")).split("\n").length;
      console.log(`${path}:${line}: file is not valid UTF-8; convert it to UTF-8`);
      failed = true;
      continue;
    }
    if (!CYRILLIC.test(text)) continue;

    const found = whole
      ? findings(text, [{ start: 0, end: text.length }])
      : findings(text, commentRanges(text, FAMILIES[family]));
    for (const f of found) {
      console.log(`${path}:${f.line}: ${f.text}`);
      failed = true;
    }
  }
  allow.forEach((a, i) => {
    if (!a.used) console.error(`warning: .language-check.json: allow[${i}] "${a.path}" matches no file`);
  });
  process.exit(failed ? 1 : 0);
}

try {
  main();
} catch (e) {
  fail(e?.message ?? String(e));
}
